/* Traduction française — domaine Processus (partie 1). */
window.PMP_FR = window.PMP_FR || {};
Object.assign(window.PMP_FR, {
'PR001': { q: 'Quel est le niveau le plus bas de la structure de découpage du projet (WBS), auquel le coût et la durée peuvent être estimés et gérés de façon fiable ?',
  o: ['Le compte de contrôle', 'Le lot de planification', 'Le lot de travail', 'L’activité'],
  e: 'Le lot de travail est le niveau le plus bas de la WBS. Les activités sont définies dans le management de l’échéancier en décomposant les lots de travail ; les comptes de contrôle se situent au-dessus des lots de travail.' },
'PR002': { q: 'Un chef de projet examine la WBS et constate que le travail des niveaux inférieurs ne couvre pas l’ensemble du travail défini dans l’énoncé du contenu. Quel principe n’est pas respecté ?',
  o: ['La règle des 80/20', 'La règle des 100 %', 'La planification par vagues successives', 'L’élaboration progressive'],
  e: 'La règle des 100 % stipule que la WBS comprend tout le travail du projet (et seulement celui-ci), et que le total du travail de chaque niveau doit correspondre au niveau supérieur.' },
'PR003': { q: 'Quels TROIS éléments constituent la référence de base du contenu ?',
  o: ['L’énoncé du contenu du projet', 'La structure de découpage du projet (WBS)', 'La matrice de traçabilité des exigences', 'Le dictionnaire de la WBS', 'La charte du projet'],
  e: 'La référence de base du contenu est constituée de l’énoncé du contenu, de la WBS et du dictionnaire de la WBS approuvés. Elle ne peut être modifiée que par une maîtrise formelle des modifications.' },
'PR004': { q: 'Le client a examiné un livrable terminé et a signé formellement un formulaire d’acceptation. Quel processus vient d’être réalisé ?',
  o: ['Maîtriser la qualité', 'Valider le contenu', 'Clore le projet ou la phase', 'Surveiller l’engagement des parties prenantes'],
  e: 'Valider le contenu est l’acceptation formelle des livrables terminés par le client ou le sponsor. Maîtriser la qualité (vérifier l’exactitude) est normalement réalisé avant Valider le contenu.' },
'PR005': { q: 'Un chef de projet veut s’assurer que chaque exigence est reliée à un objectif métier ainsi qu’aux livrables et tests qui la satisfont. Quel outil doit-il utiliser ?',
  o: ['La matrice de traçabilité des exigences', 'Le registre et le plan d’engagement des parties prenantes', 'Le dictionnaire de la WBS pour chaque lot de travail', 'Le journal des problèmes avec des liens vers les exigences'],
  e: 'La matrice de traçabilité des exigences relie les exigences à leur origine (besoins métier, objectifs) et les suit à travers la conception, les livrables et les tests.' },
'PR006': { q: 'Lors de la planification de sprint, l’équipe se rend compte qu’une user story prioritaire est trop grosse pour être terminée en un sprint. Que doit-il se passer ?',
  o: ['Prolonger le sprint de quelques jours pour pouvoir terminer la story',
      'Le Product Owner et l’équipe la découpent en stories plus petites apportant de la valeur',
      'Commencer la story et reporter le reste du travail au sprint suivant',
      'Confier la story aux développeurs les plus expérimentés pour la terminer plus vite'],
  e: 'Les stories doivent être assez petites pour être terminées dans un sprint (le « S » d’INVEST). Les grosses stories (épopées) sont découpées verticalement en tranches plus petites apportant de la valeur.' },
'PR007': { q: 'Qui est responsable de l’affinage du carnet de produit (product backlog) ?',
  o: ['Le Scrum Master, qui anime les séances d’affinage', 'Le Product Owner, en collaboration avec les développeurs', 'Le sponsor du projet, qui approuve le périmètre du produit', 'Les analystes d’affaires, qui documentent les exigences détaillées'],
  e: 'Le Product Owner est responsable du carnet de produit. L’affinage est une activité collaborative continue entre le Product Owner et les développeurs.' },
'PR008': { q: 'Les parties prenantes ont beaucoup plus d’exigences que ce qui peut être livré à la date de release. Quelle technique les aide à classer les exigences en « doit avoir », « devrait avoir », « pourrait avoir » et « n’aura pas cette fois » ?',
  o: ['Le modèle de Kano', 'MoSCoW', 'L’analyse de Pareto', 'Monte Carlo'],
  e: 'La priorisation MoSCoW classe les exigences en Must have, Should have, Could have et Won’t have (cette fois).' },
'PR009': { q: 'Une start-up ne sait pas si les clients paieront pour sa nouvelle idée de service. Quel est l’objectif principal de la construction d’un produit minimum viable (MVP) ?',
  o: ['Livrer le produit complet sur le marché au coût le plus bas possible',
      'Tester les hypothèses clés avec de vrais clients avec le moins d’effort',
      'Créer une démonstration fonctionnelle qui convainc les investisseurs de financer le produit',
      'Remplacer la collecte des exigences par un retour direct des développeurs'],
  e: 'Un MVP est le plus petit produit permettant à l’équipe de valider (ou d’invalider) des hypothèses avec de vrais utilisateurs et d’apprendre vite avant d’investir davantage.' },
'PR010': { q: 'Quelle est la différence entre les critères d’acceptation et la définition de « terminé » (DoD) ?',
  o: ['C’est la même chose, rédigée par des personnes différentes pour des publics différents',
      'Les critères d’acceptation sont propres à chaque story ; la DoD s’applique à tous les éléments de travail',
      'La DoD est rédigée par le client ; les critères d’acceptation sont rédigés par les testeurs de l’équipe',
      'Les critères d’acceptation s’appliquent à toute la release ; la DoD ne s’applique qu’à un seul sprint'],
  e: 'Les critères d’acceptation décrivent les conditions qu’une story donnée doit remplir. La définition de « terminé » est une liste partagée de critères de qualité qui s’applique à chaque incrément.' },
'PR011': { q: 'Au milieu d’un sprint, une partie prenante demande à l’équipe d’ajouter au sprint en cours une nouvelle fonctionnalité non urgente. Que doit-il se passer ?',
  o: ['L’équipe ajoute la fonctionnalité et retire du sprint une story de taille similaire',
      'Le Product Owner l’ajoute au carnet de produit pour un sprint futur',
      'Le Scrum Master évalue la demande et décide s’il faut annuler le sprint',
      'L’équipe ajoute la fonctionnalité si elle peut être terminée en faisant des heures supplémentaires'],
  e: 'L’objectif du sprint est protégé pendant le sprint. Les nouvelles demandes vont au Product Owner, qui ordonne le carnet de produit. Seul le Product Owner peut annuler un sprint, et seulement si l’objectif du sprint devient obsolète.' },
'PR012': { q: 'Un développeur ajoute une fonctionnalité de reporting non demandée, pensant que le client l’appréciera. Comment appelle-t-on cela, et comment le chef de projet doit-il réagir ?',
  o: ['Une dérive du contenu ; elle doit être approuvée via la maîtrise des modifications',
      'Une « surqualité » (gold plating) ; à éviter car elle ajoute du contenu non approuvé',
      'De l’analyse de la valeur ; à encourager car elle ajoute de la valeur',
      'De l’élaboration progressive ; c’est acceptable à mesure que les détails émergent'],
  e: 'Le gold plating consiste à ajouter des fonctionnalités au-delà des exigences convenues. Ce n’est pas une bonne pratique, car cela consomme des ressources et introduit des risques sans approbation.' },
'PR013': { q: '<p>Utilisez les informations du réseau ci-dessous.</p><table><tr><th>Activité</th><th>Durée (jours)</th><th>Prédécesseur</th></tr><tr><td>A</td><td>3</td><td>—</td></tr><tr><td>B</td><td>4</td><td>A</td></tr><tr><td>C</td><td>5</td><td>A</td></tr><tr><td>D</td><td>2</td><td>B</td></tr><tr><td>E</td><td>3</td><td>C, D</td></tr></table><p>Quelle est la durée du projet, en jours ?</p>',
  e: 'Chemins : A-B-D-E = 3+4+2+3 = 12 jours ; A-C-E = 3+5+3 = 11 jours. Le chemin critique est le plus long, A-B-D-E, donc le projet dure 12 jours.' },
'PR014': { q: '<p>Utilisez les informations du réseau ci-dessous.</p><table><tr><th>Activité</th><th>Durée (jours)</th><th>Prédécesseur</th></tr><tr><td>A</td><td>3</td><td>—</td></tr><tr><td>B</td><td>4</td><td>A</td></tr><tr><td>C</td><td>5</td><td>A</td></tr><tr><td>D</td><td>2</td><td>B</td></tr><tr><td>E</td><td>3</td><td>C, D</td></tr></table><p>Quelle est la marge totale de l’activité C, en jours ?</p>',
  e: 'Chemin critique A-B-D-E = 12 jours. Chemin A-C-E = 11 jours. C peut glisser de 12 − 11 = 1 jour sans retarder le projet ; sa marge totale est donc de 1 jour.' },
'PR015': { q: 'Quelle est la différence entre la marge totale et la marge libre ?',
  o: ['C’est la même mesure, exprimée dans des unités différentes',
      'La marge totale protège la fin du projet ; la marge libre protège le début au plus tôt des successeurs',
      'La marge libre protège la fin du projet ; la marge totale protège le début au plus tôt des successeurs',
      'La marge totale ne concerne que les activités critiques ; la marge libre seulement les non critiques'],
  e: 'La marge totale protège la date de fin du projet (ou une contrainte). La marge libre protège le début au plus tôt des successeurs immédiats. La marge libre est toujours inférieure ou égale à la marge totale.' },
'PR016': { q: 'Le projet est en retard. Le sponsor n’approuvera aucun coût supplémentaire, mais une certaine augmentation du risque est acceptable. Quelle technique le chef de projet doit-il utiliser ?',
  o: ['La compression des délais (crashing)', 'L’exécution en parallèle (fast tracking)', 'Le nivellement des ressources', 'L’ajout d’une réserve de management'],
  e: 'L’exécution en parallèle réalise simultanément des activités prévues en séquence. Elle n’ajoute généralement pas de coût direct mais augmente le risque et les reprises possibles. Le crashing ajoute des ressources et des coûts.' },
'PR017': { q: '<p>Le projet doit être raccourci de 2 jours. Les activités suivantes du chemin critique peuvent être compressées :</p><table><tr><th>Activité</th><th>Jours gagnés max</th><th>Coût de compression par jour</th></tr><tr><td>F</td><td>1</td><td>4 000 $</td></tr><tr><td>G</td><td>2</td><td>2 500 $</td></tr><tr><td>H</td><td>2</td><td>3 000 $</td></tr></table><p>En supposant que le chemin critique ne change pas, quelle option est la moins coûteuse ?</p>',
  o: ['Compresser F de 1 jour et G de 1 jour', 'Compresser G de 2 jours', 'Compresser H de 2 jours', 'Compresser F de 1 jour et H de 1 jour'],
  e: 'On compresse d’abord l’activité critique la moins chère. G coûte 2 500 $/jour × 2 jours = 5 000 $, contre 6 500 $ (F+G), 6 000 $ (H) et 7 000 $ (F+H).' },
'PR018': { q: 'Après un nivellement des ressources, la date de fin du projet a reculé de deux semaines. Pourquoi ?',
  o: ["Le nivellement ne change jamais le chemin critique ; le retard a donc une autre cause", "Il décale des activités pour lever les suraffectations et peut changer le chemin critique", "Le nivellement des ressources n’utilise que la marge libre des activités non critiques", "Le nivellement des ressources ne retarde que les activités situées hors du chemin critique"],
  e: 'Le nivellement des ressources résout les suraffectations et peut allonger l’échéancier et modifier le chemin critique. Le lissage des ressources n’utilise que la marge disponible, donc la date de fin et le chemin critique ne changent pas.' },
'PR019': { q: 'Avec une estimation à trois points (bêta / PERT), une activité a une estimation optimiste de 4 jours, la plus probable de 7 jours et pessimiste de 16 jours. Quelle est la durée attendue, en jours ?',
  e: 'Estimation bêta (PERT) = (O + 4M + P) / 6 = (4 + 28 + 16) / 6 = 48 / 6 = 8 jours. L’écart type est (P − O) / 6 = 2 jours.' },
'PR020': { q: 'Le travail des trois prochains mois est planifié en détail, tandis que les phases ultérieures sont planifiées à un niveau plus global et précisées à mesure que l’information devient disponible. Comment s’appelle cette technique ?',
  o: ['L’exécution en parallèle (fast tracking)', 'La planification par vagues successives', 'La méthode de la chaîne critique', 'Le timeboxing'],
  e: 'La planification par vagues successives est une forme d’élaboration progressive : le travail à court terme est planifié en détail, le travail futur à un niveau plus global.' },
'PR021': { q: 'Le carnet de produit restant représente 240 story points. La vélocité moyenne de l’équipe est de 30 points par sprint de deux semaines. Sans changement de périmètre, combien de sprints faut-il pour terminer le backlog ?',
  e: '240 / 30 = 8 sprints (environ 16 semaines). Les prévisions fondées sur la vélocité doivent être présentées sous forme de fourchettes et mises à jour selon l’évolution de la vélocité et du périmètre.' },
'PR022': { q: 'Un graphique burndown de sprint est resté plat pendant les six premiers jours d’un sprint de dix jours. Quelle est l’explication la plus probable ?',
  o: ['L’équipe a terminé l’essentiel de son travail tôt et attend de nouvelles stories',
      'Le travail n’est pas terminé ou pas mis à jour, peut-être à cause d’un obstacle',
      'Du périmètre a été retiré du sprint au même rythme que le travail était terminé',
      'La vélocité de l’équipe a dépassé ce que le graphique peut afficher'],
  e: 'Un burndown plat signifie que le travail restant ne diminue pas. Le Scrum Master doit rechercher des obstacles, des stories trop grosses ou un tableau non mis à jour.' },
'PR023': { q: 'Sur un graphique burnup de release, la courbe du travail terminé monte régulièrement, mais la courbe du périmètre total monte aussi. Qu’est-ce que cela indique ?',
  o: ['La vélocité de l’équipe baisse et la release sera en retard',
      'Du périmètre est ajouté, ce qui peut repousser la date d’achèvement',
      'Le projet est en avance car davantage de travail est terminé',
      'L’équipe réestime à la hausse des stories déjà terminées'],
  e: 'Un graphique burnup montre séparément le périmètre et le travail terminé : l’augmentation du périmètre est donc visible. Elle repousse la date d’achèvement prévue, sauf si des éléments sont retirés.' },
'PR024': { q: 'Une nouvelle équipe agile vient d’être formée et n’a aucun historique. La direction demande un engagement sur une date de release. Quelle est la meilleure approche ?',
  o: ['Utiliser comme base la vélocité d’une autre équipe ayant une expérience similaire',
      'Donner une estimation en fourchette et l’affiner quand la vélocité réelle sera connue',
      'Refuser d’estimer tant que l’équipe n’a pas terminé au moins trois sprints',
      'Convertir le backlog en heures et s’engager sur une date de livraison fixe'],
  e: 'Sans historique, les prévisions sont très incertaines. Fournissez une fourchette, puis utilisez la vélocité empirique de l’équipe après quelques itérations pour l’affiner.' },
'PR025': { q: 'Sur un tableau Kanban, la colonne « Tests » est pleine et les éléments s’accumulent dans « Développement terminé ». Que doit faire l’équipe ?',
  o: ['Augmenter la limite de WIP de la colonne Tests pour y faire entrer plus d’éléments',
      'Arrêter de commencer du développement et aider à vider la file des tests',
      'Ajouter une colonne « Prêt pour les tests » pour stocker les éléments en attente',
      'Faire commencer de nouvelles stories aux développeurs pendant que les testeurs vident la file'],
  e: 'Les limites de WIP rendent les goulots d’étranglement visibles. L’équipe doit arrêter de commencer et commencer à finir : aider le travail à franchir l’étape contrainte pour améliorer le flux.' },
'PR026': { q: 'Une équipe Kanban a en moyenne 20 éléments de travail en cours et en termine en moyenne 5 par semaine. Selon la loi de Little, quel est le temps de cycle moyen, en semaines ?',
  e: 'Loi de Little : temps de cycle = travail en cours / débit = 20 / 5 = 4 semaines. Réduire le travail en cours réduit le temps de cycle.' },
'PR027': { q: 'Quelle est la différence entre le délai de traitement (lead time) et le temps de cycle (cycle time) ?',
  o: ['C’est la même mesure, vue du point de vue du client et de celui de l’équipe',
      'Le lead time va de la demande à la livraison ; le temps de cycle, du début du travail à sa fin',
      'Le temps de cycle inclut l’attente avant le début du travail ; le lead time ne l’inclut pas',
      'Le lead time mesure le travail de planification ; le temps de cycle seulement le développement'],
  e: 'Le lead time est le point de vue du client (de la demande à la livraison). Le temps de cycle est celui de l’équipe (du début à la fin). Le lead time inclut l’attente avant le début du travail.' },
'PR028': { q: 'Lors d’une revue d’avancement, le projet a une valeur planifiée (PV) de 100 000 $, une valeur acquise (EV) de 90 000 $ et un coût réel (AC) de 110 000 $. Quelle est la situation du projet ?',
  o: ['En avance et sous le budget', 'En retard et au-dessus du budget', 'En avance et au-dessus du budget', 'En retard et sous le budget'],
  e: 'SPI = EV/PV = 0,90 (< 1, en retard). CPI = EV/AC = 0,82 (< 1, dépassement du budget).' },
'PR029': { q: 'Le budget à l’achèvement (BAC) est de 200 000 $. Le CPI actuel est de 0,8 et les écarts devraient se poursuivre au rythme actuel. Quelle est l’estimation à l’achèvement (EAC), en dollars ?',
  e: 'Lorsque les écarts actuels sont typiques et devraient se poursuivre, EAC = BAC / CPI = 200 000 / 0,8 = 250 000 $.' },
'PR030': { q: 'Quelle formule calcule la performance de coût à atteindre sur le travail restant pour terminer dans le budget à l’achèvement (BAC) ?',
  o: ['(BAC − EV) / (BAC − AC)', 'EV / AC', 'BAC / CPI', '(BAC − AC) / (BAC − EV)'],
  e: 'TCPI (par rapport au BAC) = travail restant / fonds restants = (BAC − EV) / (BAC − AC). Un TCPI supérieur à 1 signifie que le travail futur doit être réalisé plus efficacement.' },
'PR031': { q: 'La valeur acquise (EV) est de 50 000 $ et le coût réel (AC) de 60 000 $. Quel est l’écart de coût (CV), en dollars ? (Saisissez un nombre négatif si nécessaire.)',
  e: 'CV = EV − AC = 50 000 − 60 000 = −10 000 $. Un CV négatif signifie un dépassement du budget.' },
'PR032': { q: 'Quelle affirmation décrit correctement la réserve pour aléas et la réserve de management ?',
  o: ["Les deux sont incluses dans la référence de base des coûts et contrôlées par le chef de projet", "Aléas : risques identifiés, dans la référence des coûts ; management : risques inconnus, hors référence", "La réserve de management couvre les risques identifiés ; la réserve pour aléas couvre les inconnues inconnues et se situe hors référence", "La réserve pour aléas sert aux modifications de contenu approuvées ; la réserve de management sert aux dépassements de coûts"],
  e: 'Les réserves pour aléas (inconnues connues) font partie de la référence de base des coûts. Les réserves de management (inconnues inconnues) font partie du budget du projet mais hors référence ; leur utilisation exige généralement une approbation et une modification de la référence.' },
'PR033': { q: 'La référence de base des coûts est de 800 000 $ et la réserve de management de 50 000 $. Quel est le budget total du projet ?',
  o: ['750 000 $', '800 000 $', '850 000 $', 'Impossible à déterminer'],
  e: 'Budget du projet = référence de base des coûts (y compris réserves pour aléas) + réserve de management = 800 000 + 50 000 = 850 000 $.' },
'PR034': { q: 'Une équipe agile coûte 50 000 $ par sprint. Le backlog restant est de 300 story points et la vélocité stable de 30 points par sprint. Quel est le coût estimé pour terminer le backlog, en dollars ?',
  e: 'Sprints nécessaires = 300 / 30 = 10. Coût = 10 × 50 000 $ = 500 000 $. Les équipes agiles prévoient couramment le coût à partir du coût par itération × nombre d’itérations.' },
'PR035': { q: 'Très tôt dans un projet, avec peu d’informations détaillées, le sponsor demande une estimation des coûts. Un projet similaire a été réalisé l’année dernière. Quelle technique d’estimation est la plus appropriée ?',
  o: ['L’estimation ascendante', 'L’estimation par analogie', 'L’estimation paramétrique avec des taux unitaires détaillés', 'L’estimation à trois points pour chaque lot de travail'],
  e: 'L’estimation par analogie (descendante) utilise les données de projets passés similaires. Elle est rapide et peu coûteuse mais moins précise, ce qui convient aux phases initiales.' },
'PR036': { q: 'Un projet de construction estime le coût de pose d’une canalisation en multipliant le nombre total de mètres par le coût historique au mètre. De quelle technique s’agit-il ?',
  o: ['L’estimation par analogie', 'L’estimation paramétrique', 'L’estimation ascendante', 'Le jugement d’expert'],
  e: 'L’estimation paramétrique utilise une relation statistique entre des données historiques et des variables (coût au mètre × nombre de mètres).' },
'PR037': { q: 'La référence de base des coûts montre un pic de dépenses au 3e trimestre, mais l’organisation ne peut fournir qu’un montant fixe de financement par trimestre. Que doit faire le chef de projet ?',
  o: ['Demander la réserve de management pour couvrir les dépenses qui dépassent la limite',
      'Effectuer un rapprochement avec les limites de financement en réordonnançant le travail',
      'Retirer du contenu au 3e trimestre jusqu’à ce que les coûts prévus correspondent au financement',
      'Demander au sponsor d’augmenter la limite de financement du 3e trimestre pour l’aligner sur la référence'],
  e: 'Le rapprochement avec les limites de financement ajuste le calendrier du travail pour que les dépenses restent dans les limites périodiques de financement. Cela peut exiger des modifications de la référence de base de l’échéancier.' },
'PR038': { q: 'Associez chaque exemple de coût de la qualité à sa catégorie.',
  o: ['Former l’équipe aux normes de codage', 'Les tests et inspections', 'La reprise des défauts détectés avant la livraison', 'Les réclamations sous garantie et la perte d’affaires'],
  m: ['Coût de prévention', 'Coût d’évaluation', 'Coût de défaillance interne', 'Coût de défaillance externe'],
  e: 'Coût de la conformité = prévention + évaluation. Coût de la non-conformité = défaillance interne (détectée par le projet) + défaillance externe (détectée par le client).' },
'PR039': { q: 'Sur une carte de contrôle, sept mesures consécutives se situent au-dessus de la moyenne mais dans les limites de contrôle. Que doit conclure le chef de projet ?',
  o: ['Le processus est maîtrisé car tous les points sont dans les limites',
      'Le processus est peut-être hors contrôle et la cause doit être recherchée',
      'La limite de contrôle supérieure doit être relevée',
      'Les mesures sont aléatoires et peuvent être ignorées'],
  e: 'La « règle des sept » : sept points consécutifs ou plus d’un même côté de la moyenne indiquent une tendance non aléatoire ; le processus doit être analysé.' },
'PR040': { q: 'Une équipe qualité veut concentrer ses efforts d’amélioration sur les quelques causes responsables de la plupart des défauts. Quel outil doit-elle utiliser ?',
  o: ['Le diagramme de dispersion', 'Le diagramme de Pareto', 'La carte de contrôle', 'Le logigramme'],
  e: 'Un diagramme de Pareto classe les causes par fréquence et met en évidence les « quelques causes vitales » (environ 80/20) qui contribuent le plus au problème.' },
'PR041': { q: 'Des clients signalent des défaillances récurrentes d’un composant livré. L’équipe veut identifier les causes possibles selon des catégories comme les personnes, les méthodes, les matériaux et les machines. Quel outil est le plus adapté ?',
  o: ['Un histogramme de la fréquence des défauts', 'Un diagramme de causes et effets (Ishikawa)', 'Un graphique séquentiel des défaillances dans le temps', 'Une feuille de relevé des défaillances signalées'],
  e: 'Le diagramme de causes et effets décompose un problème en causes profondes potentielles regroupées par catégories.' },
'PR042': { q: 'Quelle est la principale différence entre Gérer la qualité et Maîtriser la qualité ?',
  o: ['Gérer la qualité inspecte les livrables ; Maîtriser la qualité audite les processus utilisés',
      'Gérer la qualité intègre la qualité dans les processus ; Maîtriser la qualité vérifie les résultats',
      'Maîtriser la qualité est réalisé par le client ; Gérer la qualité par l’équipe de projet',
      'Gérer la qualité a lieu en planification ; Maîtriser la qualité a lieu en clôture'],
  e: 'Gérer la qualité (assurance qualité) traduit le plan qualité en activités exécutables et améliore les processus. Maîtriser la qualité inspecte et vérifie les livrables pour s’assurer qu’ils respectent les exigences.' },
'PR043': { q: 'Une équipe agile découvre sans cesse des défauts d’intégration tard dans chaque sprint, lorsque le code des différents développeurs est fusionné. Quelle pratique y répond le mieux ?',
  o: ['Une phase de test plus longue à la fin de la release', 'L’intégration continue avec des tests automatisés', 'Des documents de conception plus détaillés', 'Un gel du code une semaine avant la fin du sprint'],
  e: 'L’intégration continue fusionne et teste le code fréquemment (plusieurs fois par jour), ce qui détecte tôt les problèmes d’intégration, quand ils coûtent moins cher à corriger.' },
'PR044': { q: 'Un client commande un smartphone basique avec peu de fonctionnalités, et il fonctionne parfaitement. Comment décrire ce produit ?',
  o: ['Qualité faible, classe faible', 'Classe faible, qualité élevée', 'Classe élevée, qualité faible', 'Classe élevée, qualité élevée'],
  e: 'La classe (grade) est une catégorie de caractéristiques techniques ; la qualité est le degré auquel les caractéristiques satisfont les exigences. Un produit de classe faible et de haute qualité peut être parfaitement acceptable ; une qualité faible ne l’est jamais.' },
'PR045': { q: 'Quelle affirmation reflète le mieux le management moderne de la qualité ?',
  o: ['La qualité est obtenue par l’inspection à la fin du projet', 'La qualité est planifiée, conçue et intégrée plutôt qu’inspectée', 'La qualité relève uniquement du service qualité', 'Une classe plus élevée signifie toujours une meilleure qualité'],
  e: 'La prévention plutôt que l’inspection : il est moins coûteux d’éviter les défauts que de les trouver et les corriger. Chacun est responsable de la qualité, la direction devant fournir les ressources.' },
'PR046': { q: 'Le chef de projet veut voir, pour chaque semaine, combien d’heures d’un administrateur de bases de données sont nécessaires par rapport aux heures disponibles. Quel outil est le meilleur ?',
  o: ['L’histogramme des ressources', 'La matrice RACI', 'L’organigramme fonctionnel du projet (OBS)', 'Le diagramme de réseau de l’échéancier'],
  e: 'Un histogramme des ressources montre la demande en ressources dans le temps et rend visibles les suraffectations par rapport à la disponibilité.' },
'PR047': { q: 'Quel document indique les jours ouvrés, les équipes de travail et la disponibilité de chaque ressource précise ?',
  o: ['Le calendrier des ressources', 'Le calendrier du projet', 'La structure de découpage des ressources', 'La charte d’équipe'],
  e: 'Les calendriers des ressources indiquent quand chaque ressource est disponible (jours ouvrés, équipes, congés, autres engagements).' },
'PR048': { q: 'Associez chaque type de contrat à sa caractéristique de risque.',
  o: ['Prix fixe ferme (FFP)', 'Coûts remboursables plus honoraires fixes (CPFF)', 'Temps et matériel (T&M)', 'Prix fixe avec intéressement (FPIF)'],
  m: ['Le vendeur supporte l’essentiel du risque de coût ; le prix est fixé quel que soit le coût réel',
      'L’acheteur supporte l’essentiel du risque de coût ; le vendeur est remboursé de ses coûts admissibles plus des honoraires fixes',
      'Hybride utilisé pour le renfort de personnel ou lorsqu’un énoncé des travaux précis ne peut être rédigé rapidement',
      'Prix fixe avec une prime financière pour l’atteinte ou le dépassement d’objectifs de performance convenus'],
  e: 'Les contrats à prix fixe font porter davantage de risque au vendeur, les contrats en coûts remboursables à l’acheteur. Les contrats T&M ont des caractéristiques des deux et sont souvent plafonnés.' },
'PR049': { q: 'L’acheteur a besoin qu’un fournisseur commence le travail en urgence, mais le périmètre n’est pas encore bien défini. Quel type de contrat est le plus approprié ?',
  o: ['Prix fixe ferme', 'Prix fixe avec ajustement économique du prix', 'Temps et matériel, avec un plafond à ne pas dépasser', 'Prix fixe avec intéressement'],
  e: 'Les contrats T&M permettent de démarrer rapidement quand le périmètre est flou. Un plafond protège l’acheteur contre une hausse illimitée des coûts.' },
'PR050': { q: 'Un contrat en coûts remboursables plus honoraires fixes (CPFF) prévoit un coût estimé de 100 000 $ et des honoraires fixes de 10 000 $. Le coût réel est de 120 000 $. Combien l’acheteur paiera-t-il au total, en dollars ?',
  e: 'En CPFF, le vendeur est remboursé de ses coûts réels admissibles plus les honoraires fixes, qui ne varient pas avec le coût réel : 120 000 + 10 000 = 130 000 $.' },
'PR051': { q: 'Un vendeur présente une réclamation affirmant que l’acheteur a causé des retards et doit payer des coûts supplémentaires. L’acheteur n’est pas d’accord. Selon les bonnes pratiques, quelle est la manière privilégiée de régler la réclamation ?',
  o: ["Porter la réclamation en justice, puisque les parties sont déjà en désaccord", "Négocier, puis recourir à un mode alternatif de règlement si besoin", "Résilier le contrat pour faute en raison de la réclamation du vendeur", "Suspendre les paiements jusqu’à ce que le vendeur retire sa réclamation"],
  e: 'L’administration des réclamations privilégie la négociation. Si les parties ne s’entendent pas, un mode alternatif de règlement des différends (médiation ou arbitrage) est utilisé avant le contentieux.' },
'PR052': { q: 'L’organisation se demande si elle doit développer un composant en interne ou l’acheter à un fournisseur. Quelle technique doit-elle utiliser ?',
  o: ['L’analyse « faire ou acheter »', 'La conférence des soumissionnaires', 'L’analyse de la valeur acquise', 'Le benchmarking'],
  e: 'L’analyse « faire ou acheter » compare les coûts (directs et indirects), les capacités, les risques et les considérations stratégiques d’une production interne par rapport à un approvisionnement externe.' },
'PR053': { q: 'Quel est l’objectif principal d’une conférence des soumissionnaires ?',
  o: ['Négocier le prix final et les conditions du contrat avec le vendeur préféré',
      'S’assurer que tous les vendeurs potentiels ont la même compréhension de l’approvisionnement',
      'Évaluer les propositions des vendeurs selon les critères et choisir l’offre retenue',
      'Examiner l’historique de performance des vendeurs avant l’attribution du contrat'],
  e: 'Les conférences des soumissionnaires donnent à tous les vendeurs potentiels les mêmes informations et la possibilité de poser des questions, ce qui garantit l’équité.' },
'PR054': { q: 'Un vendeur livre systématiquement en retard par rapport à l’échéancier contractuel. Que doit faire le chef de projet en premier ?',
  o: ['Envoyer un avis de résiliation pour faute afin de protéger l’échéancier du projet',
      'Examiner les termes du contrat et la performance, puis notifier formellement le vendeur',
      'Retenir le prochain paiement jusqu’à ce que le vendeur rattrape son retard',
      'Commencer à chercher un vendeur de remplacement capable de livrer à temps'],
  e: 'Les approvisionnements doivent être gérés selon le contrat. Le chef de projet examine les termes et les données de performance, puis communique formellement (par exemple un avis), avec les services achats/juridique si nécessaire.' },
'PR055': { q: 'Un acheteur souhaite une relation agile avec un fournisseur, dans laquelle le périmètre peut évoluer tandis que le budget reste maîtrisé. Quelle approche contractuelle est la plus adaptée ?',
  o: ['Un contrat à prix fixe ferme avec un périmètre détaillé et entièrement défini',
      'Un budget fixe par itération, avec un périmètre variable priorisé par le client',
      'Un contrat en coûts remboursables pour que le fournisseur absorbe les changements sans renégociation',
      'Un contrat en temps et matériel avec un comité de contrôle pour chaque modification'],
  e: 'Les contrats agiles fixent souvent le temps et le coût par incrément et laissent le périmètre varier selon les priorités (des clauses « money for nothing, change for free » permettent une sortie anticipée ou l’échange d’éléments du périmètre).' },
'PR056': { q: 'Tous les livrables du contrat ont été livrés. Que doit-il se passer avant de pouvoir clore l’approvisionnement ?',
  o: ['Le vendeur envoie sa facture finale et l’acheteur la paie',
      'L’acheteur accepte formellement le travail et notifie par écrit son achèvement',
      'Le chef de projet libère l’équipe et archive les fichiers du projet',
      'Les leçons apprises de l’approvisionnement sont consignées et archivées'],
  e: 'Clore un approvisionnement exige l’acceptation formelle des livrables, le règlement des réclamations en cours, le paiement final et une notification écrite formelle de l’achèvement, généralement via l’administration des achats.' },
'PR057': { q: 'Un nouveau projet comporte des exigences matérielles bien comprises et fixées par la réglementation, et des exigences d’application mobile qui devraient évoluer selon les retours des utilisateurs. Quelle approche de livraison est la plus appropriée ?',
  o: ['Prédictive pour tout le projet, puisque le matériel est réglementé', 'Agile pour tout le projet, puisque l’application a besoin de retours fréquents', 'Hybride : prédictive pour le matériel, adaptative pour l’application mobile', 'Kanban pour le matériel et Scrum pour l’application mobile'],
  e: 'L’adaptation (tailoring) choisit l’approche de chaque composant selon la certitude des exigences, les contraintes réglementaires et le besoin de retours. L’approche hybride combine les deux.' },
'PR058': { q: 'Lors du choix d’une approche de développement, quel facteur plaide le plus en faveur d’une approche adaptative (agile) ?',
  o: ['Des exigences stables, bien définies et approuvées tôt', 'Une forte incertitude sur les exigences et un besoin de retours fréquents', 'Une documentation réglementaire stricte exigée à chaque passage de phase', 'Un livrable utilisable seulement une fois entièrement terminé'],
  e: 'Une forte incertitude sur les exigences, un rythme de changement élevé et la possibilité de livrer des incréments utilisables favorisent les approches adaptatives.' },
'PR059': { q: 'Quels sont les principaux résultats de la planification de sprint ?',
  o: ['Une feuille de route produit et un plan de release mis à jour', 'Un objectif de sprint et un carnet de sprint', 'Une définition de « terminé » et une charte d’équipe', 'Une prévision de vélocité et un burndown de sprint'],
  e: 'La planification de sprint produit l’objectif du sprint et le carnet de sprint (éléments sélectionnés plus le plan pour les livrer).' },
'PR060': { q: 'Quel est l’objectif principal de la mêlée quotidienne (daily scrum) ?',
  o: ['Rendre compte de l’avancement au Scrum Master et au Product Owner', 'Inspecter la progression vers l’objectif du sprint et adapter le plan', 'Identifier et résoudre les problèmes techniques avec toute l’équipe', 'Ajouter au carnet de produit les nouveaux éléments de l’équipe'],
  e: 'La mêlée quotidienne est un court événement de planification et de synchronisation pour les développeurs, pas un compte rendu à la direction.' },
'PR061': { q: 'Quelle est la différence entre la revue de sprint et la rétrospective de sprint ?',
  o: ["La revue inspecte les processus et outils de l’équipe ; la rétrospective inspecte l’incrément produit", "La revue inspecte l’incrément avec les parties prenantes ; la rétro, le fonctionnement de l’équipe", "La revue est réservée à l’équipe ; la rétrospective inclut aussi les parties prenantes et le sponsor", "La revue a lieu à chaque sprint ; la rétrospective seulement à la fin d’une release"],
  e: 'Revue de sprint : ce qui a été construit, avec les retours des parties prenantes, et l’adaptation du backlog. Rétrospective : comment l’équipe a travaillé (personnes, processus, outils) et ce qu’il faut améliorer.' },
'PR062': { q: 'L’équipe ne parvient pas à estimer une story car elle exige une technologie qu’elle n’a jamais utilisée. Que doit faire l’équipe ?',
  o: ['Attribuer une estimation élevée pour couvrir l’incertitude liée à la nouvelle technologie',
      'Créer un spike limité dans le temps pour étudier la technologie',
      'Déplacer la story en bas du backlog jusqu’à ce que la technologie soit mieux connue',
      'Demander au Product Owner de l’estimer, puisque l’équipe manque d’expérience'],
  e: 'Un spike est une activité de recherche ou d’expérimentation limitée dans le temps qui apporte les connaissances nécessaires pour estimer ou réduire un risque technique.' },
'PR063': { q: 'Au fil du temps, la vélocité de l’équipe a baissé parce que le code est devenu difficile à modifier. Que doit faire l’équipe ?',
  o: ['Continuer à ajouter des fonctionnalités et prévoir plus tard une release dédiée au refactoring',
      'Rendre la dette technique visible et planifier le refactoring avec le Product Owner',
      'Arrêter le travail sur les fonctionnalités et réécrire le système avec une architecture plus propre',
      'Allonger le sprint pour laisser à l’équipe le temps de nettoyer le code'],
  e: 'La dette technique ralentit la livraison. L’équipe doit la rendre visible, la prioriser avec le Product Owner et la rembourser par un refactoring régulier.' },
'PR064': { q: 'Le sponsor demande pourquoi les résultats réels diffèrent du plan. Quelle technique le chef de projet doit-il utiliser pour déterminer la cause et l’ampleur de l’écart ?',
  o: ['L’analyse des écarts', 'La décomposition', 'L’analyse des alternatives', 'Le benchmarking'],
  e: 'L’analyse des écarts examine les différences entre la performance prévue et réelle, y compris leurs causes, leur impact et les actions correctives.' },
'PR065': { q: 'Tous les livrables du projet sont terminés. Que doit faire le chef de projet en premier lors de la clôture ?',
  o: ['Libérer l’équipe de projet pour qu’elle passe à d’autres projets', 'Obtenir l’acceptation formelle des livrables', 'Archiver les documents du projet dans le référentiel de l’organisation', 'Finaliser le registre des leçons apprises avec l’équipe'],
  e: 'L’acceptation formelle des livrables vient en premier. Le chef de projet transfère ensuite le produit, finalise les leçons apprises, clôt les contrats, archive les documents et libère les ressources.' },
'PR066': { q: 'Le sponsor met fin prématurément à un projet car l’analyse de rentabilisation n’est plus valable. Que doit faire le chef de projet ?',
  o: ["Arrêter immédiatement tout travail et réaffecter l’équipe à d’autres projets de l’organisation", "Mener la clôture : documenter l’état d’avancement et les leçons apprises", "Terminer d’abord les livrables déjà en cours avant de clore le projet", "Remettre les documents du projet au PMO et libérer l’équipe"],
  e: 'Les projets arrêtés prématurément doivent tout de même être clôturés correctement : documenter le niveau d’achèvement, transférer les livrables partiels et capter les leçons apprises.' },
'PR067': { q: 'Quand faut-il recueillir les leçons apprises ?',
  o: ['À la fin du projet, lors du processus de clôture', 'Tout au long du projet, puis les finaliser à la clôture', 'Après chaque problème ou échec majeur', 'À chaque revue de passage de phase, comme l’exige la gouvernance'],
  e: 'Les leçons apprises sont recueillies tout au long du projet (en agile, par les rétrospectives) pour être appliquées immédiatement, puis transférées à l’organisation à la clôture.' },
'PR068': { q: 'Un nouveau système va être transféré à l’équipe d’exploitation. Que doit garantir le chef de projet pour faciliter la transition ?',
  o: ['L’équipe de projet continue à assurer le support du système jusqu’à la correction de tous les défauts',
      'L’exploitation est formée, avec documentation et processus de support en place',
      'Le système est déployé et l’exploitation est informée après la mise en service',
      'Le sponsor signe formellement la documentation de transfert'],
  e: 'La planification de la transition comprend la formation, la documentation, les processus de support et un transfert formel afin que l’organisation opérationnelle puisse réaliser les bénéfices.' },
'PR069': { q: '<p>Le Product Owner utilise le Weighted Shortest Job First (WSJF = coût du retard ÷ taille du travail) pour prioriser les fonctionnalités.</p><table><tr><th>Fonctionnalité</th><th>Coût du retard</th><th>Taille du travail</th></tr><tr><td>Alpha</td><td>20</td><td>10</td></tr><tr><td>Bravo</td><td>12</td><td>3</td></tr><tr><td>Charlie</td><td>30</td><td>15</td></tr><tr><td>Delta</td><td>8</td><td>8</td></tr></table><p>Quelle fonctionnalité doit être réalisée en premier ?</p>',
  o: ['Alpha', 'Bravo', 'Charlie', 'Delta'],
  e: 'WSJF : Alpha 2,0, Bravo 4,0, Charlie 2,0, Delta 1,0. Bravo a le WSJF le plus élevé : elle apporte le plus de valeur par unité d’effort et doit être réalisée en premier.' },
'PR070': { q: 'Sur un diagramme de flux cumulé, la bande « En revue » ne cesse de s’élargir tandis que les autres bandes restent stables. Qu’est-ce que cela indique ?',
  o: ['L’équipe termine les éléments en revue plus vite qu’avant', 'Un goulot d’étranglement en revue, où le travail s’accumule', 'Le périmètre diminue à mesure que les éléments passent en revue', 'L’équipe a atteint un flux stable et prévisible'],
  e: 'Une bande qui s’élargit dans un diagramme de flux cumulé montre que le travail entre dans une étape plus vite qu’il n’en sort, ce qui signifie un goulot d’étranglement. Le temps de cycle va augmenter.' },
'PR071': { q: 'Un projet a un SPI de 1,2 et un CPI de 0,8. Comment le chef de projet doit-il l’interpréter ?',
  o: ['En retard et sous le budget', 'En avance et au-dessus du budget', 'En avance et sous le budget', 'En retard et au-dessus du budget'],
  e: 'SPI > 1 signifie que plus de travail a été réalisé que prévu (en avance). CPI < 1 signifie que le travail réalisé a coûté plus que prévu (dépassement du budget). Cela peut arriver lorsque des ressources supplémentaires accélèrent le travail.' },
'PR072': { q: 'Un projet a un BAC de 500 000 $. Il est achevé à 40 % et le coût réel à date est de 250 000 $. Quel est le CPI ? (Saisissez un nombre décimal, par exemple 0,95.)',
  e: 'EV = 40 % × 500 000 = 200 000 $. CPI = EV / AC = 200 000 / 250 000 = 0,8.' },
'PR073': { q: 'Les utilisateurs ne savent pas exactement ce qu’ils attendent d’un nouveau portail client et ont du mal à décrire leurs exigences. Quelle technique de recueil est la plus efficace ?',
  o: ['Les questionnaires', 'Le prototypage', 'L’analyse documentaire', 'Le benchmarking'],
  e: 'Les prototypes donnent aux utilisateurs quelque chose de concret auquel réagir, ce qui permet d’affiner les exigences par cycles de retours.' },
'PR074': { q: 'Quel type de dépendance est exigé par le contrat ou la loi, ou est inhérent à la nature du travail (par exemple, couler les fondations avant de monter les murs) ?',
  o: ['La dépendance discrétionnaire', 'La dépendance obligatoire', 'La dépendance externe', 'La logique préférentielle'],
  e: 'Les dépendances obligatoires (logique impérative) sont exigées légalement ou contractuellement, ou inhérentes au travail. Les dépendances discrétionnaires (logique préférentielle) reposent sur les bonnes pratiques et peuvent être modifiées pour exécuter en parallèle.' },
'PR075': { q: 'La peinture ne peut commencer que 2 jours après la fin du plâtrage, pour laisser sécher. Comment modéliser cela dans l’échéancier ?',
  o: ['Fin-début avec une avance de 2 jours', 'Fin-début avec un décalage de 2 jours', 'Début-début avec une avance de 2 jours', 'Fin-fin avec un décalage de 2 jours'],
  e: 'Un décalage (lag) est un retard imposé au successeur. La peinture (successeur) commence 2 jours après la fin du plâtrage (prédécesseur) : FD + 2 jours de décalage.' },
'PR076': { q: 'Quelle méthode d’ordonnancement ajoute des tampons à la fin des chaînes d’activités et se concentre sur le travail contraint par les ressources plutôt que sur la marge totale ?',
  o: ['La méthode du chemin critique', 'La méthode de la chaîne critique', 'PERT', 'La méthode des antécédents'],
  e: 'La méthode de la chaîne critique utilise des tampons agrégés (projet et alimentation) pour protéger l’échéancier contre l’incertitude et tient compte des ressources limitées.' },
'PR077': { q: 'Dans un échéancier, qu’est-ce qu’un jalon ?',
  o: ['Une activité d’une durée d’au moins un jour', 'Un événement significatif de durée nulle', 'La dernière activité du chemin critique', 'Une activité récapitulative marquant une phase du projet'],
  e: 'Les jalons marquent des événements significatifs (par exemple l’achèvement d’un livrable majeur) et ont une durée nulle.' },
'PR078': { q: 'Quand le chef de projet doit-il arrêter de décomposer la WBS ?',
  o: ["Quand chaque élément peut être réalisé par une personne en un jour ou moins", "Quand les lots de travail peuvent être estimés, attribués et maîtrisés", "Quand la WBS a atteint au moins cinq niveaux de décomposition", "Quand chaque membre de l’équipe s’est vu attribuer au moins un lot de travail"],
  e: 'La décomposition se poursuit jusqu’à ce que le travail puisse être estimé, planifié, attribué et maîtrisé. Une décomposition excessive crée une charge inutile.' },
'PR079': { q: 'Quelle affirmation décrit le mieux un système Kanban ?',
  o: ['Le travail est poussé vers l’équipe selon un calendrier fixe', 'Le travail est tiré dans une étape seulement quand il y a de la capacité', 'Le travail est planifié en itérations de durée fixe', 'Chaque membre travaille sur plusieurs éléments à la fois pour maximiser l’utilisation'],
  e: 'Kanban est un système tiré : un nouveau travail ne commence que lorsqu’il y a de la capacité, contrôlée par des limites de WIP explicites, afin d’optimiser le flux.' },
'PR080': { q: 'L’équipe commence souvent dans un sprint des stories floues, puis se retrouve bloquée en attendant des réponses. Que doit-elle mettre en place ?',
  o: ['Des sprints plus longs pour absorber le temps d’attente', 'Une définition de « prêt » (DoR) pour les éléments du backlog', 'Un comité de contrôle des modifications pour les nouvelles stories', 'Un gel des exigences avant chaque sprint'],
  e: 'Une définition de « prêt » fixe les critères que les éléments doivent remplir (clairs, dimensionnés, testables, dépendances connues) avant d’entrer dans un sprint.' },
'PR081': { q: 'Un membre de l’équipe utilise une version obsolète d’une spécification technique et construit un composant de façon incorrecte. Quel plan aurait dû l’éviter ?',
  o: ['Le plan de management des communications', 'Le plan de gestion de la configuration', 'Le plan de management des risques', 'Le plan de management des ressources'],
  e: 'Le plan de gestion de la configuration définit comment les artefacts sont identifiés, versionnés et mis à jour pour que chacun utilise les bonnes versions.' },
'PR082': { q: 'Quel document autorise formellement l’existence d’un projet et donne au chef de projet l’autorité d’utiliser les ressources de l’organisation ?',
  o: ['Le plan de management du projet', 'La charte du projet', 'L’analyse de rentabilisation', 'L’énoncé des travaux'],
  e: 'La charte du projet, émise par le sponsor ou l’initiateur, autorise formellement le projet et l’autorité du chef de projet.' },
'PR083': { q: 'Quelles DEUX références de base font partie du plan de management du projet ?',
  o: ['La référence de base de l’échéancier', 'Le registre des risques', 'La référence de base des coûts', 'Le journal des problèmes', 'Le registre des leçons apprises'],
  e: 'Les références de base sont celles du contenu, de l’échéancier et des coûts (souvent intégrées dans la référence de mesure de la performance). Les registres et journaux sont des documents de projet, pas des références de base.' },
'PR084': { q: 'La direction pousse une équipe à augmenter sa vélocité à chaque sprint. Quel est le résultat le plus probable ?',
  o: ['Plus de valeur livrée, car l’équipe devient plus efficace', 'Une inflation des story points et une qualité moindre, sans réel gain', 'Des prévisions plus précises, car la vélocité se stabilise', 'Un meilleur moral, car l’équipe se sent stimulée par des objectifs plus élevés'],
  e: 'La vélocité est un outil de planification, pas un objectif de performance. Pousser à l’augmenter entraîne des estimations gonflées et des raccourcis sur la qualité (loi de Goodhart).' },
'PR085': { q: 'Un chef de projet doit choisir entre deux fournisseurs. La décision doit équilibrer le prix, la capacité technique, les performances passées et le délai de livraison. Quelle technique est la meilleure ?',
  o: ['Choisir le fournisseur le moins cher', 'Une notation pondérée des critères', 'Une estimation par analogie des contrats passés', 'Le seul jugement d’expert du sponsor'],
  e: 'L’analyse décisionnelle multicritère / notation pondérée évalue les options selon des critères pondérés, ce qui donne une sélection objective et documentée.' },
'PR086': { q: 'Le Product Owner veut obtenir au plus tôt les retours de vrais utilisateurs sur une nouvelle fonctionnalité. Quelle approche y répond le mieux ?',
  o: ['Livrer toutes les fonctionnalités ensemble à la fin du projet', 'Livrer fréquemment de petits incréments fonctionnels et recueillir des retours', 'Rédiger un document d’exigences détaillé et le faire approuver par les utilisateurs', 'Construire un prototype complet avant de commencer tout développement'],
  e: 'La livraison fréquente d’incréments fonctionnels apportant de la valeur permet des retours précoces, réduit les risques et accélère la création de valeur.' },
'PR087': { q: 'Le chef de projet a terminé l’échéancier du projet et l’équipe est d’accord. Que faut-il pour qu’il devienne la référence de base de l’échéancier ?',
  o: ['Il est publié sur le site du projet pour toutes les parties prenantes', 'Il est approuvé, puis ne change plus que par la maîtrise des modifications', 'Les membres de l’équipe le signent pour confirmer leur engagement', 'Il est saisi et enregistré dans le logiciel de planification'],
  e: 'Une référence de base est la version approuvée d’un plan, utilisée pour comparaison avec les résultats réels. Ses modifications exigent une maîtrise formelle des modifications.' },
'PR088': { q: 'Une activité a une estimation optimiste de 6 jours et pessimiste de 18 jours. Quel est l’écart type de l’estimation bêta (PERT), en jours ?',
  e: 'Écart type = (P − O) / 6 = (18 − 6) / 6 = 2 jours.' },
'PR089': { q: 'Dans Scrum, qui est responsable de créer à chaque sprint un incrément utilisable respectant la définition de « terminé » ?',
  o: ['Le Product Owner', 'Les développeurs', 'Le Scrum Master', 'Les parties prenantes'],
  e: 'Les développeurs sont responsables de créer un incrément utilisable à chaque sprint et de respecter la définition de « terminé ».' },
'PR090': { q: 'Un chef de projet élabore un plan de management de la qualité. Quelle est la meilleure approche pour définir les normes de qualité ?',
  o: ['Réutiliser les normes de qualité du dernier projet similaire pour gagner du temps de planification',
      'Identifier les exigences et normes de qualité applicables et la façon de démontrer la conformité',
      'Laisser l’équipe définir les normes de qualité pendant l’exécution, à mesure que le travail se précise',
      'Définir les normes après les premières inspections, quand on voit où se trouvent les défauts'],
  e: 'Planifier le management de la qualité identifie les exigences et normes de qualité (organisationnelles, réglementaires, client) et la façon dont le projet démontrera sa conformité.' },
'PR091': { q: 'Le chef de projet remarque que le travail réalisé s’écarte du plan tout en restant dans les seuils définis. Que doit-il faire ?',
  o: ['Soumettre une demande de modification pour rebaser l’échéancier', 'Surveiller la tendance et envisager des actions préventives', 'Escalader l’écart au comité de pilotage', 'Demander à l’équipe des heures supplémentaires pour supprimer l’écart'],
  e: 'Les écarts dans les seuils sont gérés par le chef de projet, généralement par la surveillance et des actions préventives. L’escalade est requise lorsque les seuils sont dépassés.' },
'PR092': { q: 'Une équipe agile a réalisé 25, 31, 28 et 32 points lors des quatre derniers sprints. Quelle vélocité utiliser pour planifier la prochaine release ?',
  o: ['32, le résultat le plus récent, qui reflète la performance actuelle', '25, le résultat le plus bas, pour garder une marge de sécurité', 'Environ 29, la moyenne récente, présentée avec une fourchette', '35, pour motiver l’équipe à continuer de progresser'],
  e: 'Utilisez la moyenne des sprints récents (ici 29) et communiquez une fourchette (par exemple 25–32) pour refléter l’incertitude.' },
'PR093': { q: 'L’échéancier nécessite un inspecteur électrique pendant une journée, mais l’inspecteur n’est disponible qu’une semaine sur deux. Quel document le chef de projet doit-il consulter ?',
  o: ['Le calendrier du projet', 'Le calendrier des ressources', 'Le registre des risques', 'Le rapport de performance du travail'],
  e: 'Le calendrier des ressources indique quand des ressources précises (y compris externes) sont disponibles, ce qui influence l’ordonnancement des activités.' },
'PR094': { q: 'Un projet de construction a un périmètre clair et un coût de modification élevé une fois le travail commencé. Quel cycle de vie est le plus approprié ?',
  o: ['Prédictif (en cascade)', 'Agile (Scrum)', 'Kanban', 'Itératif avec des releases hebdomadaires'],
  e: 'Lorsque le périmètre est bien compris et que le coût du changement est élevé, un cycle de vie prédictif avec une planification initiale détaillée est approprié.' },
'PR095': { q: 'L’analyse de la valeur acquise montre un CPI de 0,95 et il reste de nombreux mois de projet. Le sponsor demande la prévision de coût la plus réaliste. Le chef de projet estime que la performance passée ne reflète pas l’avenir, car un problème de coût majeur a été résolu. Que faut-il utiliser ?',
  o: ['EAC = BAC / CPI, car le CPI reflète la performance réelle jusqu’ici', 'EAC = AC + (BAC − EV)', 'EAC = AC + [(BAC − EV) / (CPI × SPI)]', 'EAC = BAC, puisque le problème de coût a été résolu'],
  e: 'Si les écarts passés sont atypiques et que le travail futur devrait se dérouler comme prévu, EAC = AC + (BAC − EV). S’ils sont typiques, on utilise BAC / CPI.' },
'PR096': { q: 'Une équipe s’apprête à commencer une release. Le Product Owner veut une vue d’ensemble du moment où les fonctionnalités majeures seront livrées au cours des prochains trimestres. Que faut-il créer ?',
  o: ['Un diagramme de Gantt détaillé', 'Une feuille de route produit (roadmap)', 'Un carnet de sprint', 'Un graphique burndown'],
  e: 'Une feuille de route produit montre la séquence et le calendrier prévus des fonctionnalités ou résultats majeurs dans le temps. Elle est mise à jour au fil des apprentissages.' },
'PR097': { q: 'À la fin du sprint, une story est terminée à 90 % mais ne respecte pas la définition de « terminé ». Que doit-il advenir d’elle ?',
  o: ['Compter 90 % de ses points dans la vélocité pour refléter le travail fait', 'La remettre dans le carnet de produit pour que le Product Owner la repriorise', 'Prolonger le sprint de deux jours pour pouvoir terminer la story', 'La marquer comme terminée et créer une nouvelle story pour le reste du travail'],
  e: 'Un travail qui ne respecte pas la définition de « terminé » ne fait pas partie de l’incrément et ne compte pas dans la vélocité. Il retourne dans le carnet de produit, où le Product Owner décide de sa priorité.' },
'PR098': { q: 'Une équipe de 5 développeurs travaille 6 heures productives par jour sur un sprint de 10 jours ouvrés. Un développeur sera en congé pendant 4 jours. Quelle est la capacité disponible de l’équipe pour le sprint, en heures ?',
  e: 'Capacité totale = 5 × 6 × 10 = 300 heures. Congé = 1 × 6 × 4 = 24 heures. Capacité disponible = 300 − 24 = 276 heures.' },
'PR099': { q: 'L’équipe doit estimer rapidement 120 éléments du backlog pour la planification initiale de la release. Quelle technique est la plus efficace ?',
  o: ['Le planning poker, en discutant chaque élément jusqu’au consensus', 'L’estimation par affinité, en groupes de tailles relatives', 'L’estimation ascendante des tâches en heures', 'La technique Delphi avec des tours anonymes par courriel'],
  e: 'L’estimation par affinité (par exemple tailles de t-shirt ou estimation murale) permet à une équipe de dimensionner rapidement un grand nombre d’éléments en les comparant entre eux.' },
'PR100': { q: 'Une équipe découpe une grosse fonctionnalité en stories intitulées « construire la base de données », « construire l’API » et « construire l’interface utilisateur ». Quel est le principal problème de cette approche ?',
  o: ['Les stories sont trop petites pour être estimées de façon fiable', 'Ce sont des tranches horizontales qui n’apportent aucune valeur utilisable seules', 'Les stories dépendent trop du Product Owner', 'Il n’y a aucun problème ; c’est une façon standard de découper le travail'],
  e: 'Les stories doivent être des tranches verticales traversant toutes les couches, chacune apportant une petite valeur utilisable et testable. Le découpage horizontal retarde les retours et la valeur.' },
'PR101': { q: 'Quelles caractéristiques décrivent un carnet de produit bien tenu (DEEP) ?',
  o: ['Détaillé, Estimé, Élaboré techniquement, Priorisé', 'Détaillé de façon appropriée, Estimé, Émergent, Priorisé', 'Documenté, Exhaustif, Estimé, Planifié en totalité', 'Défini, Efficace, Émergent, Planifié par release'],
  e: 'DEEP : les éléments du haut sont détaillés de façon appropriée, les éléments sont estimés, le backlog est émergent (il évolue) et il est priorisé (ordonné).' },
'PR102': { q: 'À mi-sprint, les développeurs se rendent compte qu’ils ne pourront pas terminer tous les éléments sélectionnés, mais que l’objectif du sprint reste atteignable. Que doivent-ils faire ?',
  o: ['Demander au Product Owner d’annuler le sprint et d’en planifier un nouveau', 'Renégocier le carnet de sprint avec le Product Owner en conservant l’objectif', 'Faire des heures supplémentaires pour terminer tous les éléments comme prévu', 'Réduire les tests des éléments restants pour pouvoir les terminer'],
  e: 'L’objectif du sprint est fixe, mais le carnet de sprint peut être clarifié et renégocié avec le Product Owner au fil des apprentissages. La qualité n’est pas réduite.' },
'PR103': { q: 'Une organisation veut mettre en production de nouvelles fonctionnalités plusieurs fois par jour avec un faible risque. Quelle combinaison de pratiques y répond le mieux ?',
  o: ['Des cycles de release plus longs avec une phase finale complète de tests de non-régression', 'Des pipelines CI/CD avec tests automatisés et feature toggles', 'Des déploiements manuels approuvés par un comité des modifications pour chaque release', 'Un gel du code une semaine avant chaque release pour stabiliser le système'],
  e: 'Les pipelines CI/CD avec tests automatisés rendent chaque modification petite et vérifiable, et les feature toggles découplent le déploiement de la mise à disposition, ce qui réduit le risque.' },
'PR104': { q: 'Quelle pratique XP fait travailler deux développeurs sur un même poste, l’un écrivant le code et l’autre le relisant en temps réel ?',
  o: ['Le développement piloté par les tests', 'La programmation en binôme', 'La propriété collective du code', 'Le refactoring'],
  e: 'La programmation en binôme améliore la qualité et diffuse les connaissances dans l’équipe. Les rôles (pilote et copilote) sont échangés fréquemment.' },
'PR105': { q: 'Une équipe pratique le développement piloté par les tests (TDD). Quel est l’ordre correct des étapes ?',
  o: ['Écrire le code, écrire ses tests, puis refactorer', 'Écrire un test qui échoue, le faire passer, puis refactorer', 'Concevoir la solution, écrire le code, puis écrire les tests', 'Écrire d’abord tous les tests de la story, puis tout le code'],
  e: 'Le TDD suit le cycle rouge-vert-refactorisation : écrire un test qui échoue (rouge), le faire passer (vert), puis améliorer la conception (refactorisation).' },
'PR106': { q: 'Un programme utilise un échéancier directeur prédictif avec des jalons contractuels, mais les composants logiciels sont construits par des équipes agiles. Comment le chef de projet doit-il intégrer le travail agile à l’échéancier directeur ?',
  o: ['Convertir tout le travail agile en un diagramme de Gantt détaillé par tâche', 'Relier les releases aux jalons du programme et les suivre par des burnups de release', 'Exclure le travail agile de l’échéancier directeur et en rendre compte séparément', 'Demander aux équipes agiles de planifier tous les sprints à l’avance pour coller aux jalons'],
  e: 'En environnement hybride, les releases agiles sont alignées sur les jalons prédictifs. L’avancement au niveau des releases (burnups, prévisions de vélocité) alimente l’échéancier directeur sans microgérer les tâches.' },
'PR107': { q: 'Un projet agile rend compte de son avancement par la valeur acquise. Le plan de release compte 200 story points pour un budget de 400 000 $. Après plusieurs sprints, 80 points sont terminés et 180 000 $ ont été dépensés. Quel est le CPI ?',
  o: ['0,89', '1,13', '0,80', '0,44'],
  e: 'EVM agile : EV = (80 / 200) × 400 000 = 160 000 $. CPI = EV / AC = 160 000 / 180 000 = 0,89, soit un dépassement du budget.' },
'PR108': { q: 'Pourquoi les équipes agiles préfèrent-elles être pluridisciplinaires, avec des membres « en T » ?',
  o: ['Pour réduire les coûts en ayant besoin de moins de spécialistes par équipe', 'Pour livrer sans passations et permettre aux membres d’aider à lever les goulots', 'Pour que chaque membre devienne expert dans tous les domaines techniques', 'Pour que l’équipe ne dépende plus d’un Product Owner pour ses décisions'],
  e: 'Les équipes pluridisciplinaires réduisent les passations et les dépendances. Les profils en T (expertise profonde dans un domaine, large ailleurs) peuvent se mobiliser sur les goulots et améliorer le flux.' },
'PR109': { q: 'Quel format de user story est le plus couramment recommandé ?',
  o: ['« Le système doit… »', '« En tant que <rôle>, je veux <capacité>, afin de <bénéfice>. »', '« Tâche : <description>, Heures : <estimation> »', '« Étant donné <contexte>, quand <événement>, alors <résultat>. »'],
  e: 'Le format rôle-objectif-bénéfice garde les stories centrées sur l’utilisateur et la valeur. « Étant donné / quand / alors » est un format de critères d’acceptation (BDD), pas de la story elle-même.' },
'PR110': { q: 'Une équipe Kanban subit occasionnellement des incidents de production à traiter immédiatement, en plus du travail habituel sur les fonctionnalités. Comment le tableau doit-il gérer cela ?',
  o: ["Suspendre toutes les limites de WIP à chaque incident de production", "Définir une classe de service « urgente » aux règles explicites", "Traiter les incidents entièrement en dehors du système Kanban", "Réserver en permanence un développeur qui attend les incidents"],
  e: 'Des classes de service aux politiques explicites (comme une voie urgente strictement limitée) laissent passer le travail urgent sans détruire la prévisibilité du travail standard.' },
'PR111': { q: 'Une équipe choisit la durée de ses sprints. Les exigences du produit changent souvent et les parties prenantes veulent des retours rapides. Quel est le meilleur choix ?',
  o: ['Un sprint plus court, par exemple d’une ou deux semaines', 'Un sprint plus long, par exemple de deux mois', 'Aucun sprint ; tout livrer à la fin', 'Faire varier aléatoirement la durée de chaque sprint'],
  e: 'Des itérations plus courtes offrent des retours plus rapides et davantage d’occasions de s’adapter, ce qui convient à un rythme de changement élevé. La durée des sprints doit rester constante pour créer un rythme.' },
'PR112': { q: 'Dans un projet hybride, l’équipe matériel utilise un comité de contrôle des modifications et l’équipe logiciel un carnet de produit. Une modification affecte les deux. Quelle est la meilleure façon de la traiter ?',
  o: ['Traiter la modification uniquement dans le carnet de produit, puisque l’agile accueille le changement',
      'Évaluer l’impact conjoint ; utiliser le CCB pour le matériel baseliné et le backlog pour le logiciel',
      'Traiter la modification uniquement via le CCB, puisqu’elle touche le périmètre matériel baseliné',
      'Laisser chaque équipe décider indépendamment comment traiter sa propre partie de la modification'],
  e: 'La gestion des modifications hybride combine les mécanismes : le contenu baseliné (prédictif) passe par la maîtrise intégrée des modifications, tandis que le travail adaptatif est priorisé dans le backlog. L’impact est évalué conjointement.' },
'PR113': { q: 'Quelles DEUX techniques permettent de compresser l’échéancier d’un projet sans changer son contenu ?',
  o: ['La compression des délais (crashing)', 'L’exécution en parallèle (fast tracking)', 'Le nivellement des ressources', 'L’ajout de décalages entre les activités', 'La planification par vagues successives'],
  e: 'Le crashing ajoute des ressources (et des coûts) aux activités critiques ; le fast tracking fait se chevaucher des activités (en ajoutant du risque). Le nivellement des ressources et les décalages allongent généralement l’échéancier.' },
'PR114': { q: 'Quels TROIS éléments sont des artefacts Scrum ?',
  o: ['Le carnet de produit', 'Le carnet de sprint', 'L’incrément', 'Le diagramme de Gantt', 'La charte du projet'],
  e: 'Scrum définit trois artefacts : le carnet de produit (avec l’objectif produit), le carnet de sprint (avec l’objectif du sprint) et l’incrément (avec la définition de « terminé »).' }
});
